                additional information related to this step.
        """
        self._id = id_
        self._name = name
        self._parameters = parameters
        self._metadata_store = metadata_store

        self._inputs: Dict[str, ArtifactView] = OrderedDict()
        self._outputs: Dict[str, ArtifactView] = OrderedDict()

