        """compute meld type"""
        content = self.content # optimize access speed
        if not content:
            return EMPTY
        assert content[0].lower() in 'xdwsbcfy', content
        if len(self) == 1:
            result = SINGLE
        elif len(self) == 2:
            result = PAIR
        elif len(self)== 4:
            starts = ''.join([content[0], content[2], content[4], content[6]])
            if starts.upper() == starts:
                result = PUNG
                self.__valid = False
            elif content[:6].lower() + content[6].upper() + content[7] == content:
                result = CLAIMEDKONG
            else:
                result = KONG
        elif self.__isChow():
            result = CHOW
        elif len(self) == 3:
            result = PUNG
        else:
            result = REST
        if result == CHOW:
            assert content[::2] == content[0] * 3
        elif result != REST:
            if (content[:2] * len(self)).lower() != content.lower():
                result = REST
        return result

